#' Style an Individual Element
#'
#' Adds or updates an override for one element of a chart, without replacing
#' the styles of other elements: a gene, a gene label, a gene coordinate, or
#' the title or subtitle of a cluster title, footer or label. Use this in an
#' editor and in the R code generated by it. Legend labels and markers can
#' also be edited individually by group and part.
#'
#' @param GC_chart A GC chart object.
#' @param component The component to edit: `"genes"`, `"labels"`,
#'   `"coordinates"`, `"clusterTitle"`, `"clusterFooter"`, `"clusterLabel"` or `"legend"`.
#' @param row_id For genes, labels and coordinates: the gene's `rowID` in
#'   `GC_chart$x$data`, also returned in `input$<outputId>_select$data$rowID`
#'   and double-click event data.
#' @param ... Named element options, using JavaScript names, e.g. `fill`,
#'   `stroke`, `strokeWidth`, `marker`, `markerSize`, `fontSize`, `dx`, `dy`
#'   or `rotate`. Labels, titles and subtitles also accept `text` to override
#'   their displayed text. Coordinates accept `show = FALSE` to leave them out
#'   and `tick`, a list of options for their tick.
#' @param cluster For cluster titles, footers and labels: the name or number of
#'   the cluster.
#' @param part For cluster titles, footers and labels: `"title"` or
#'   `"subtitle"`; for the legend: `"label"` or `"marker"`.
#' @param end For coordinates: `"start"` or `"end"` for the coordinate of the
#'   start or end of the gene, or `NULL` (default) for both.
#' @param group For the legend: its original group value, also returned as
#'   `data` in click, selection and double-click events. Editing label text
#'   does not change this value or the input data. Marker edits affect only
#'   the legend patch.
#' @param reset Logical, remove this element's override instead of updating it.
#'
#' @details Overrides of genes, labels and coordinates match the row ID rather
#'   than the element's drawing index, so sorting, reverse clusters, resize and
#'   repeated gene names do not change their target. Row IDs are assigned by
#'   [GC_chart()] after filtering missing coordinates. Reproducing an edit
#'   requires the same input rows in the same order; replacing or reordering
#'   the input data requires remapping edits. These overrides take precedence
#'   over group styles and index-based styles. Reset removes the override,
#'   restoring underlying styles. Call this after the component's normal
#'   configuration (e.g. [GC_clusterTitle()]), which replaces its overrides.
#'   Legend overrides also take precedence over `GC_legend(groupStyle = ...)`;
#'   resetting one part restores its group and global styles.
#'
#' @return The chart with the element override updated.
#' @examples
#' genes <- data.frame(start = c(90, 10), end = c(130, 50), name = c("a", "a"))
#' GC_chart(genes) %>%
#'   GC_labels("name") %>%
#'   GC_clusterTitle("Cluster", subtitle = "Subtitle") %>%
#'   GC_element_style("genes", row_id = 1, fill = "red", marker = "box") %>%
#'   GC_element_style("labels", row_id = 1, text = "Edited", fontSize = "16px") %>%
#'   GC_element_style("clusterTitle", cluster = 1, part = "subtitle",
#'                    fontStyle = "italic", fill = "grey")
#'
#' GC_chart(data.frame(start = 10, end = 40, family = "A"), group = "family") %>%
#'   GC_element_style("legend", group = "A", part = "label", text = "Family A") %>%
#'   GC_element_style("legend", group = "A", part = "marker", fill = "red")
#' @export
GC_element_style <- function(GC_chart,
                             component = c("genes", "labels", "coordinates", "clusterTitle",
                                           "clusterFooter", "clusterLabel", "legend"),
                             row_id = NULL, ..., cluster = NULL, part = NULL, end = NULL,
                             reset = FALSE, group = NULL) {
  component <- match.arg(component)
  by_row <- component %in% c("genes", "labels", "coordinates")
  if (component == "legend") {
    if (!is.null(row_id) || !is.null(cluster) || !is.null(end)) {
      stop("Use 'group' and 'part' to identify a legend label or marker.")
    }
    column <- GC_chart$x$legend$group
    if (length(group) != 1 || is.na(group) || !length(column) ||
        !group %in% GC_chart$x$data[[column]]) {
      stop("'group' must identify one group in the legend.")
    }
    if (!identical(part, "label") && !identical(part, "marker")) {
      stop("'part' must be \"label\" or \"marker\" for the legend.")
    }
  } else if (!is.null(group)) {
    stop("'group' is only used for the legend.")
  }
  if (by_row) {
    if (!is.numeric(row_id) || length(row_id) != 1 || is.na(row_id) ||
        !is.finite(row_id) || !row_id %in% GC_chart$x$data$rowID) {
      stop("'row_id' must identify one row in the chart's data.")
    }
    if (!is.null(cluster) || !is.null(part)) {
      stop("Use 'row_id' to identify a gene, label or coordinate, not 'cluster' or 'part'.")
    }
    if (!is.null(end) && (component != "coordinates" ||
                          !identical(end, "start") && !identical(end, "end"))) {
      stop("'end' must be \"start\" or \"end\", and only for coordinates.")
    }
  } else if (component != "legend") {
    if (!is.null(row_id) || !is.null(end)) {
      stop("Use 'cluster' and 'part' to identify a title or subtitle, not 'row_id' or 'end'.")
    }
    if (length(cluster) != 1 || is.na(cluster)) stop("'cluster' must be one cluster.")
    cluster <- suppressWarnings(getUpdatedClusters(GC_chart, cluster))
    if (is.null(cluster)) stop("'cluster' must be the name or number of a cluster of the chart.")
    if (!identical(part, "title") && !identical(part, "subtitle")) {
      stop("'part' must be \"title\" or \"subtitle\".")
    }
  }
  if (!is.logical(reset) || length(reset) != 1 || is.na(reset)) {
    stop("'reset' must be TRUE or FALSE.")
  }
  style <- list(...)
  if (length(style) && (is.null(names(style)) || anyNA(names(style)) ||
                        any(!nzchar(names(style))) || anyDuplicated(names(style)))) {
    stop("Element options must have unique, nonempty names.")
  }
  if (any(names(style) %in% c("index", "rowID", "part", "end"))) {
    stop("Identify the element with 'row_id', 'cluster', 'part' or 'end', not with element options.")
  }
  if (reset && length(style)) stop("Do not supply element options with 'reset = TRUE'.")

  if (component == "legend") {
    items <- GC_chart$x$legend$itemStyle
    matched <- vapply(items, function(item) {
      identical(item$group, group) && identical(item$part, part)
    }, logical(1))
    previous <- if (any(matched)) items[[which(matched)[1]]] else list()
    items <- items[!matched]
    if (!reset) {
      override <- utils::modifyList(previous, style)
      override$group <- group
      override$part <- part
      items <- c(items, list(override))
    }
    GC_chart$x$legend$itemStyle <- unname(items)
    return(GC_chart)
  }

  # The series entry of the component, and what identifies the element in it
  key <- switch(component, clusterFooter = "footer", component)
  id <- if (by_row) c(list(rowID = row_id), if (!is.null(end)) list(end = end)) else list(part = part)
  same <- function(item) {
    if (by_row) {
      identical(as.numeric(item$rowID), as.numeric(row_id)) && identical(item$end, end)
    } else {
      identical(item$part, part)
    }
  }

  clusters <- if (by_row) names(GC_chart$x$series) else cluster
  for (name in clusters) {
    series <- GC_chart$x$series[[name]]
    if (by_row && !row_id %in% series$data$rowID) next
    items <- series[[key]]$itemStyle
    matched <- vapply(items, same, logical(1))
    previous <- if (any(matched)) items[[which(matched)[1]]] else list()
    items <- items[!matched]
    if (!reset) {
      override <- utils::modifyList(previous, style)
      override[names(id)] <- id
      items <- c(items, list(override))
    }
    GC_chart$x$series[[name]][[key]]$itemStyle <- unname(items)
  }
  GC_chart
}
